        var k = r();
        stars.push({ x: Math.floor(r() * w), y: Math.floor(r() * h), c: k < 0.6 ? "dusk" : k < 0.85 ? "mauve" : k < 0.95 ? "stone" : "ice", p: r() * 10, big: r() < 0.04 });
