      var muteB = Lux.$('[data-act="mute"]', box), fullB = Lux.$('[data-act="full"]', box);
      var seek = Lux.$(".seek", box), fill = Lux.$(".fill", box), knob = Lux.$(".knob", box), time = Lux.$(".time", box);
